def entry(id, title, text, basis, date, *refs, entity_id=None):
    result = dict(id=id, title=title, text=text, basis=basis, date=date,
                  evidence=[dict(source_id=source_id, reference=reference) for source_id, reference in refs])
    if entity_id:
        result["entity_id"] = entity_id
    return result


def relationship(id, source_node, target_node, relation_kind, title, text, basis, date, *refs, entity_id=None):
    return {**entry(id, title, text, basis, date, *refs, entity_id=entity_id),
            "source_node": source_node, "target_node": target_node, "relation_kind": relation_kind}


